import{store,getContext}from"@wordpress/interactivity";function ctx(){try{return getContext()}catch(e){return{}}}store("jetonomy/connect-app",{state:{get busy(){return!!ctx().busy},get connected(){return!!ctx().connected},get deepLink(){return ctx().deepLink||""},get error(){return ctx().error||""}},actions:{*approve(){var t=ctx();if(!t.busy&&!t.connected){t.busy=!0,t.error="";try{var e=yield fetch(t.restUrl+"auth/app-connect",{method:"POST",headers:{"Content-Type":"application/json","X-WP-Nonce":t.restNonce},body:JSON.stringify({scheme:t.scheme,bridge_token:t.bridgeToken,app_name:t.appName,app_id:t.appId,state:t.state})}),r=yield e.json();e.ok&&r&&r.deep_link?(t.deepLink=r.deep_link,t.connected=!0,window.location.href=r.deep_link):t.error=r&&r.message||t.errorText}catch(e){t.error=t.errorText}t.busy=!1}}}});